CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "recruiter_id" integer not null, "title" varchar not null, "department" varchar not null, "description" text not null, "experience" varchar not null, "salary_range" varchar, "application_deadline" date not null, "status" varchar not null default 'open', "created_at" datetime, "updated_at" datetime, foreign key("recruiter_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "job_skills" ("id" integer primary key autoincrement not null, "job_id" integer not null, "skill_id" integer not null, "is_mandatory" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("job_id") references "jobs"("id") on delete cascade, foreign key("skill_id") references "skills"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "candidates" ("id" integer primary key autoincrement not null, "user_id" integer, "name" varchar not null, "email" varchar not null, "phone" varchar, "experience_years" numeric not null default '0', "education" varchar, "skills_summary" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
