CREATE TABLE IF NOT EXISTS "resumes" ("id" integer primary key autoincrement not null, "candidate_id" integer not null, "file_path" varchar not null, "file_name" varchar not null, "file_size" integer, "parsed_text" text, "parsed_data" text, "status" varchar not null default 'uploaded', "created_at" datetime, "updated_at" datetime, foreign key("candidate_id") references "candidates"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "applications" ("id" integer primary key autoincrement not null, "job_id" integer not null, "candidate_id" integer not null, "resume_id" integer, "status" varchar not null default 'Applied', "skill_score" numeric not null default '0', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("job_id") references "jobs"("id") on delete cascade, foreign key("candidate_id") references "candidates"("id") on delete cascade, foreign key("resume_id") references "resumes"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "application_status_histories" ("id" integer primary key autoincrement not null, "application_id" integer not null, "from_status" varchar, "to_status" varchar not null, "changed_by_user_id" integer, "comment" text, "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("changed_by_user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "interviews" ("id" integer primary key autoincrement not null, "application_id" integer not null, "interviewer_id" integer not null, "scheduled_at" datetime not null, "meeting_link" varchar not null, "status" varchar not null default 'scheduled', "feedback" text, "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("interviewer_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "technical_tasks" ("id" integer primary key autoincrement not null, "application_id" integer not null, "assigned_by_user_id" integer not null, "title" varchar not null, "description" text not null, "deadline" datetime not null, "status" varchar not null default 'Pending', "reminder_sent_at" datetime, "created_at" datetime, "updated_at" datetime, "attachments" text, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("assigned_by_user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "task_submissions" ("id" integer primary key autoincrement not null, "technical_task_id" integer not null, "repository_url" varchar, "notes" text, "file_path" varchar, "submitted_at" datetime not null, "score" integer, "feedback" text, "created_at" datetime, "updated_at" datetime, foreign key("technical_task_id") references "technical_tasks"("id") on delete cascade);
